// Proxy (Next.js 16; formerly middleware): per-request CSP nonce + security headers. Generated by
// `eos scaffold web-security`; yours to edit. Already have a proxy.ts? Merge this logic into it instead.
// Keep proxy cheap: no database calls, and never the only authorization check (CVE-2025-29927).
// Start with CSP_REPORT_ONLY=1 in staging, fix violations, then enforce (unset it).
import { type NextRequest, NextResponse } from "next/server";
import { buildCsp, createNonce, securityHeaders } from "./lib/csp";

export function proxy(request: NextRequest) {
  const nonce = createNonce();
  const csp = buildCsp(nonce, {
    dev: process.env.NODE_ENV === "development",
    reportUri: process.env.CSP_REPORT_URI,
  });
  const header = process.env.CSP_REPORT_ONLY === "1" ? "Content-Security-Policy-Report-Only" : "Content-Security-Policy";
  const requestHeaders = new Headers(request.headers);
  requestHeaders.set("x-nonce", nonce);
  requestHeaders.set(header, csp); // Next.js reads the nonce from here and applies it to its own scripts
  const response = NextResponse.next({ request: { headers: requestHeaders } });
  response.headers.set(header, csp);
  for (const [k, v] of Object.entries(securityHeaders)) response.headers.set(k, v);
  return response;
}

export const config = {
  matcher: [
    // Skip API routes, static files, image optimisation, favicon and prefetches (Next.js CSP guide).
    {
      source: "/((?!api|_next/static|_next/image|favicon.ico).*)",
      missing: [
        { type: "header", key: "next-router-prefetch" },
        { type: "header", key: "purpose", value: "prefetch" },
      ],
    },
  ],
};
